import java.util.*;abstract class Question{int points;Question(int p){points=p;}abstract boolean evaluate(String a);}class MCQ extends Question{String correct;MCQ(String c,int p){super(p);correct=c;}boolean evaluate(String a){return correct.equalsIgnoreCase(a);}}class TrueFalse extends Question{boolean correct;TrueFalse(boolean c,int p){super(p);correct=c;}boolean evaluate(String a){return Boolean.parseBoolean(a)==correct;}}class ShortAnswer extends Question{String correct;ShortAnswer(String c,int p){super(p);correct=c;}boolean evaluate(String a){return correct.equalsIgnoreCase(a.trim());}}class Student{String name;Student(String n){name=n;}}class Examination{String name;List<Question> questions=new ArrayList<>();Examination(String n){name=n;}}class Attempt{Student student;Examination exam;Map<Question,String> answers=new HashMap<>();boolean submitted;Attempt(Student s,Examination e){student=s;exam=e;}void answer(Question q,String a){if(submitted)throw new IllegalStateException();answers.put(q,a);}int submit(){if(submitted)throw new IllegalStateException();submitted=true;int score=0;for(Question q:exam.questions)if(answers.containsKey(q)&&q.evaluate(answers.get(q)))score+=q.points;return score;}}public class Main{public static void main(String[]a){}}